Input: {"question": "Who is the main actor in the film \"Let George Do It\"?", "original_source_segments": {"D1S1": {"document_number": 1, "doc_id": "ramdocs-0493-46c1ae9ca900:d00", "start": 0, "end": 17, "text": "Let George Do It!"}, "D1S2": {"document_number": 1, "doc_id": "ramdocs-0493-46c1ae9ca900:d00", "start": 18, "end": 174, "text": "Let George Do It (US: \"To Hell With Hitler\") is a 1940 British black-and-white comedy musical war film directed by Marcel Varnel and starring George Formby."}, "D1S3": {"document_number": 1, "doc_id": "ramdocs-0493-46c1ae9ca900:d00", "start": 175, "end": 310, "text": "It was produced by Michael Balcon for Associated Talking Pictures and its successor, Ealing Studios, and distributed in the UK by ABFD."}, "D1S4": {"document_number": 1, "doc_id": "ramdocs-0493-46c1ae9ca900:d00", "start": 311, "end": 397, "text": "This was the first comedy from this studio to deal directly with the Second World War."}, "D1S5": {"document_number": 1, "doc_id": "ramdocs-0493-46c1ae9ca900:d00", "start": 398, "end": 577, "text": "At the beginning of the Second World War, before Germany invaded Norway, a ukulele player in a British dance band playing at a Bergen hotel, is found dead during a radio broadcast"}, "D2S1": {"document_number": 2, "doc_id": "ramdocs-0493-46c1ae9ca900:d01", "start": 0, "end": 10, "text": "block off."}, "D2S2": {"document_number": 2, "doc_id": "ramdocs-0493-46c1ae9ca900:d01", "start": 11, "end": 155, "text": "Translate Translated from by Review by PUNQ ★★½ You know it's wartime when even Charlie Chaplin is sent to Bergen, Norway to spy on the Germans!"}, "D2S3": {"document_number": 2, "doc_id": "ramdocs-0493-46c1ae9ca900:d01", "start": 156, "end": 199, "text": "And he sure puts a jolly spin on espionage."}, "D2S4": {"document_number": 2, "doc_id": "ramdocs-0493-46c1ae9ca900:d01", "start": 200, "end": 256, "text": "At least he gets people to smile during difficult times."}, "D2S5": {"document_number": 2, "doc_id": "ramdocs-0493-46c1ae9ca900:d01", "start": 257, "end": 308, "text": "Worth it for Chaplin's encounter with Adolf Hitler!"}, "D2S6": {"document_number": 2, "doc_id": "ramdocs-0493-46c1ae9ca900:d01", "start": 309, "end": 402, "text": "Translate Translated from by Review by Danaé Joyful and funny little British wartime musical."}, "D2S7": {"document_number": 2, "doc_id": "ramdocs-0493-46c1ae9ca900:d01", "start": 403, "end": 426, "text": "Love Chaplin ’ s tunes."}, "D2S8": {"document_number": 2, "doc_id": "ramdocs-0493-46c1ae9ca900:d01", "start": 427, "end": 520, "text": "Translate Translated from by Review by TomPines As a Charlie Chaplin enthusiast, I'm probably"}, "D3S1": {"document_number": 3, "doc_id": "ramdocs-0493-46c1ae9ca900:d02", "start": 0, "end": 110, "text": "Let George Do It (1938 film) Let George Do It is a 1938 comedy starring popular stage comedian George Wallace."}, "D3S2": {"document_number": 3, "doc_id": "ramdocs-0493-46c1ae9ca900:d02", "start": 111, "end": 164, "text": "It was the first of two films Wallace made for Ken G."}, "D3S3": {"document_number": 3, "doc_id": "ramdocs-0493-46c1ae9ca900:d02", "start": 165, "end": 242, "text": "Hall at Cinesound Productions, the other one being \"Gone to the Dogs\" (1939)."}, "D3S4": {"document_number": 3, "doc_id": "ramdocs-0493-46c1ae9ca900:d02", "start": 243, "end": 342, "text": "Hall later called Wallace \"in my opinion, easily the best comedian that this country has produced.\""}, "D3S5": {"document_number": 3, "doc_id": "ramdocs-0493-46c1ae9ca900:d02", "start": 343, "end": 461, "text": "The plot concerns a man, Joe Blake, who works as a stage hand in a vaudeville theatre headlined by Mysto the magician."}, "D3S6": {"document_number": 3, "doc_id": "ramdocs-0493-46c1ae9ca900:d02", "start": 462, "end": 543, "text": "When he finds out that the girl he is in love with, Molly, is getting married, he"}, "D4S1": {"document_number": 4, "doc_id": "ramdocs-0493-46c1ae9ca900:d03", "start": 0, "end": 87, "text": "The background music was supplied by Eddie Dunstedter, initially with a full orchestra."}, "D4S2": {"document_number": 4, "doc_id": "ramdocs-0493-46c1ae9ca900:d03", "start": 88, "end": 302, "text": "When television supplanted radio as the country's primary home entertainment, radio budgets got skimpier and skimpier and Dunstedter's orchestra was replaced by an organ(played by Dunstedter), as from January 1949."}, "D4S3": {"document_number": 4, "doc_id": "ramdocs-0493-46c1ae9ca900:d03", "start": 303, "end": 434, "text": "Let George Do It (radio) Let George Do It was an American radio drama series produced from 1946 to 1954 by Owen and Pauline Vinson."}, "D4S4": {"document_number": 4, "doc_id": "ramdocs-0493-46c1ae9ca900:d03", "start": 435, "end": 531, "text": "Bob Bailey starred as private investigator George Valentine; Olan Soule voiced the role in 1954."}, "D4S5": {"document_number": 4, "doc_id": "ramdocs-0493-46c1ae9ca900:d03", "start": 532, "end": 598, "text": "Don Clark directed the scripts by David Victor and Jackson Gillis."}, "D4S6": {"document_number": 4, "doc_id": "ramdocs-0493-46c1ae9ca900:d03", "start": 599, "end": 634, "text": "The few earliest episodes were more"}, "D5S1": {"document_number": 5, "doc_id": "ramdocs-0493-46c1ae9ca900:d04", "start": 0, "end": 244, "text": "harron68 - favorite favorite favorite favorite - November 13 , 2015 Subject : How Well George Did It An earlier series before Johnny Dollar , it suffers a bit from intrusive organ cues and Bob Bailey more tuff guy than he later was as Johnny D."}, "D5S2": {"document_number": 5, "doc_id": "ramdocs-0493-46c1ae9ca900:d04", "start": 245, "end": 257, "text": "Drama is ..."}, "D5S3": {"document_number": 5, "doc_id": "ramdocs-0493-46c1ae9ca900:d04", "start": 258, "end": 266, "text": "More ..."}, "D5S4": {"document_number": 5, "doc_id": "ramdocs-0493-46c1ae9ca900:d04", "start": 267, "end": 349, "text": "the emphasis here with the fine actress Frances Robinson the frustrated romantic ."}, "D5S5": {"document_number": 5, "doc_id": "ramdocs-0493-46c1ae9ca900:d04", "start": 350, "end": 443, "text": "Scripts are good though the denouement is often rushed as Bob pushes the suspect to confess ."}, "D5S6": {"document_number": 5, "doc_id": "ramdocs-0493-46c1ae9ca900:d04", "start": 444, "end": 508, "text": "In sum , a fine show , just not quite the Johnny Dollar series ."}, "D5S7": {"document_number": 5, "doc_id": "ramdocs-0493-46c1ae9ca900:d04", "start": 509, "end": 512, "text": "..."}, "D5S8": {"document_number": 5, "doc_id": "ramdocs-0493-46c1ae9ca900:d04", "start": 513, "end": 528, "text": "Less Reviewer :"}, "D6S1": {"document_number": 6, "doc_id": "ramdocs-0493-46c1ae9ca900:d05", "start": 0, "end": 635, "text": "Do It 1950-06-05 ( 195 ) The Witch of Mill Hollow.autogenerated.txt download 25.7K Let George Do It 1950-06-12 ( 196 ) The Iron Cat.autogenerated.txt download 24.3K Let George Do It 1950-06-19 ( 197 ) Solo in Whispers.autogenerated.txt download 25.4K Let George Do It 1950-06-26 ( 198 ) Most Likely to Die.autogenerated.txt download 27.2K Let George Do It 1950-07-03 ( 199 ) The Scream of the Eagle.autogenerated.txt download 24.3K Let George Do It 1950-07-10 ( 200 ) Island in the Desert.autogenerated.txt download 26.0K Let George Do It 1950-07-17 ( 201 ) Eleven O'Clock.autogenerated.txt download 24.5K Let George Do It 1950-07-24 ("}}, "original_cards": [{"doc_id": "ramdocs-0493-46c1ae9ca900:d00", "card_id": "ramdocs-0493-46c1ae9ca900:d00:c0", "entity": "George Formby", "scope": "main actor", "claim": "The 1940 British film Let George Do It stars George Formby.", "answer": "George Formby", "quote": "Let George Do It (US: \"To Hell With Hitler\") is a 1940 British black-and-white comedy musical war film directed by Marcel Varnel and starring George Formby.", "original_document_number": 1}, {"doc_id": "ramdocs-0493-46c1ae9ca900:d02", "card_id": "ramdocs-0493-46c1ae9ca900:d02:c0", "entity": "George Wallace", "scope": "main actor", "claim": "Let George Do It is a 1938 comedy starring popular stage comedian George Wallace.", "answer": "George Wallace", "quote": "Let George Do It (1938 film) Let George Do It is a 1938 comedy starring popular stage comedian George Wallace.", "original_document_number": 3}], "current_answers": ["George Formby", "George Wallace", "Bob Bailey", "Olan Soule"], "candidate_answers": [{"candidate_id": "R0", "answer": "George Formby", "origin": "initial"}, {"candidate_id": "R1", "answer": "George Wallace", "origin": "initial"}, {"candidate_id": "R2", "answer": "Bob Bailey", "origin": "coverage_addition"}, {"candidate_id": "R3", "answer": "Olan Soule", "origin": "coverage_addition"}]}

